-- Onboarding deliberately chose a joint-centric vocabulary because people are injured at knees
-- and shoulders, which are not muscle groups (008_onboarding.sql). That was right, and it left a
-- gap: the plan builder needs to turn "avoid knee" into a set of exercises. This is that gap,
-- expressed as a junction so an admin can tune it without a migration.
CREATE TABLE IF NOT EXISTS body_area_muscle_map (
  body_area TEXT NOT NULL CHECK (body_area IN (
    'neck', 'shoulder', 'elbow', 'wrist', 'upper-back', 'lower-back',
    'hip', 'knee', 'ankle', 'foot', 'chest', 'abdomen', 'other')),
  muscle_group_id INTEGER NOT NULL REFERENCES muscle_groups(id) ON DELETE CASCADE,
  PRIMARY KEY (body_area, muscle_group_id)
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS idx_body_area_map_muscle ON body_area_muscle_map (muscle_group_id);

-- Seeded by SLUG, never by id: the ids are whatever the 003 seed happened to allocate.
INSERT OR IGNORE INTO body_area_muscle_map (body_area, muscle_group_id)
SELECT 'knee', id FROM muscle_groups WHERE slug IN ('quads', 'hamstrings', 'calves', 'glutes');
