CREATE TABLE IF NOT EXISTS body_area_muscle_map (
  -- The vocabulary is copied VERBATIM from onboarding_limitations (008:77-80), kebab-case included.
  -- A second spelling of the same idea is how a join silently returns nothing.
  body_area TEXT NOT NULL CHECK (body_area IN (
    'neck', 'shoulder', 'elbow', 'wrist', 'upper-back', 'lower-back',
    'hip', 'knee', 'ankle', 'foot', 'chest', 'abdomen', 'other'
  )),
  muscle_group_id INTEGER NOT NULL REFERENCES muscle_groups(id) ON DELETE CASCADE,
  -- 'loads' drives severity='avoid' (remove the exercise outright); 'stabilises' drives
  -- severity='caution' (keep it, flag it). Without the distinction a knee complaint would remove
  -- every exercise a calf ever stabilises.
  relation TEXT NOT NULL DEFAULT 'loads' CHECK (relation IN ('loads', 'stabilises')),
  PRIMARY KEY (body_area, muscle_group_id)
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS idx_body_area_by_muscle ON body_area_muscle_map (muscle_group_id, relation);

-- Seeded by SLUG, never by id: ids are assignment order, slugs are the stable key (003:3-5).
